const raw = $input.first().json;
let text = "";
if (raw.text) text = raw.text;
else if (raw.message) text = typeof raw.message === "string" ? raw.message : (raw.message.content || raw.message.text || "");
else if (raw.response) text = raw.response;
else text = JSON.stringify(raw);
text = text.replace(/^```(?:json)?\s*\n?/gm, "").replace(/```\s*$/gm, "").trim();
let mov;
try { mov = JSON.parse(text); } catch (e) { return [{ json: { valid: false, error: "JSON invalido: " + e.message } }]; }
const tipo = mov.tipo;
if (!["ingreso", "egreso", "transferencia"].includes(tipo)) { return [{ json: { valid: false, error: "tipo invalido: " + tipo } }]; }
if (!mov.contraparte) { return [{ json: { valid: false, error: "contraparte faltante" } }]; }
if (typeof mov.monto !== "number" || mov.monto <= 0) { return [{ json: { valid: false, error: "monto invalido: " + mov.monto } }]; }
if (!mov.divisa || !["CLP", "USD", "ARS", "EUR"].includes(mov.divisa)) { return [{ json: { valid: false, error: "divisa invalida: " + mov.divisa } }]; }
if (!mov.fechaMovimiento) { return [{ json: { valid: false, error: "fechaMovimiento faltante" } }]; }
if (tipo === "egreso" && !mov.categoriaEgreso) { return [{ json: { valid: false, error: "categoriaEgreso faltante" } }]; }
if (tipo === "ingreso" && !mov.categoriaIngreso) { return [{ json: { valid: false, error: "categoriaIngreso faltante" } }]; }
if (tipo === "transferencia" && !mov.direccionTransferencia) { return [{ json: { valid: false, error: "direccionTransferencia faltante" } }]; }
mov.valid = true;
return [{ json: mov }];
